package zombie.iso; public final class IsoGridSquare {public final int x,y,z;public final zombie.util.list.PZArrayList<IsoObject> objects=new zombie.util.list.PZArrayList<>();public IsoChunk chunk; public int invalidations;public boolean blocked;public IsoGridSquare(int x,int y,int z){this.x=x;this.y=y;this.z=z;}public int getX(){return x;}public int getY(){return y;}public int getZ(){return z;}public IsoChunk getChunk(){return chunk;} public void invalidateRenderChunkLevel(long flags){if(flags!=256L)throw new AssertionError("native level flags");invalidations++;}public zombie.util.list.PZArrayList<IsoObject> getObjects(){return objects;}public boolean isAdjacentTo(IsoGridSquare s){return s!=null&&z==s.z&&Math.abs(x-s.x)<=1&&Math.abs(y-s.y)<=1;}public void add(IsoObject o){o.square=this;o.index=objects.size();objects.add(o);}}
